# Prepare batch tasks
batches = df.groupby('batch_id')

tasks = []
for batch_id, batch_data in batches:
    task = {
        'batch_id': batch_id,
        'data': batch_data.to_dict('records'),
        'function': 'process_batch',
        'params': {'quality_threshold': 95}
    }
    tasks.append(task)
